<?php
class WeComWebhookService
{
    private $pdo;
    private $config;
    public function __construct($pdo,$config){$this->pdo=$pdo;$this->config=$config;}
    public function settings(){
        $keys=array('wecom_enabled','wecom_order_enabled','wecom_ticket_enabled','wecom_payment_enabled','wecom_webhook_url');
        $rows=array();$in=implode(',',array_fill(0,count($keys),'?'));$s=$this->pdo->prepare('SELECT * FROM system_settings WHERE setting_key IN ('.$in.')');$s->execute($keys);foreach($s as $row)$rows[$row['setting_key']]=$row;
        $url='';if(isset($rows['wecom_webhook_url'])&&!empty($rows['wecom_webhook_url']['setting_ciphertext']))$url=(new CryptoService($this->config))->decrypt($rows['wecom_webhook_url']['setting_ciphertext'],$rows['wecom_webhook_url']['setting_nonce'],$rows['wecom_webhook_url']['setting_tag']);
        return array('enabled'=>!empty($rows['wecom_enabled']['setting_value'])&&$rows['wecom_enabled']['setting_value']==='1','order_enabled'=>!empty($rows['wecom_order_enabled']['setting_value'])&&$rows['wecom_order_enabled']['setting_value']==='1','ticket_enabled'=>!empty($rows['wecom_ticket_enabled']['setting_value'])&&$rows['wecom_ticket_enabled']['setting_value']==='1','payment_enabled'=>!empty($rows['wecom_payment_enabled']['setting_value'])&&$rows['wecom_payment_enabled']['setting_value']==='1','url'=>$url,'configured'=>$url!=='');
    }
    public static function validateWebhookUrl($url){$p=parse_url(trim((string)$url));if(!is_array($p)||strtolower(isset($p['scheme'])?$p['scheme']:'')!=='https'||strtolower(isset($p['host'])?$p['host']:'')!=='qyapi.weixin.qq.com'||isset($p['user'])||isset($p['pass'])||isset($p['fragment'])||isset($p['port'])||($p['path']!=='/cgi-bin/webhook/send')||empty($p['query']))throw new InvalidArgumentException('请输入有效的企业微信机器人 Webhook 地址。');parse_str($p['query'],$q);if(count($q)!==1||empty($q['key'])||!is_string($q['key'])||strlen($q['key'])>200)throw new InvalidArgumentException('企业微信 Webhook key 格式无效。');return rtrim(trim($url),' ');}
    public function sendText($text){$settings=$this->settings();if(!$settings['configured'])throw new RuntimeException('企业微信 Webhook 尚未配置。');return $this->request($settings['url'],array('msgtype'=>'text','text'=>array('content'=>substr((string)$text,0,1800))));}
    public function sendPayload($payload){$settings=$this->settings();if(!$settings['configured'])throw new RuntimeException('企业微信 Webhook 尚未配置。');$event=isset($payload['event_type'])?$payload['event_type']:'';$enabled=$settings['enabled'];if($event==='order_created')$enabled=$enabled&&$settings['order_enabled'];elseif($event==='ticket_created')$enabled=$enabled&&$settings['ticket_enabled'];elseif($event==='payment_confirmed')$enabled=$enabled&&$settings['payment_enabled'];if(!$enabled)return false;$lines=array('【云盾通知】',isset($payload['title'])?$payload['title']:'业务通知');foreach(isset($payload['lines'])&&is_array($payload['lines'])?$payload['lines']:array() as $line)$lines[]=(string)$line;return $this->request($settings['url'],array('msgtype'=>'text','text'=>array('content'=>substr(implode("\n",$lines),0,1800))));}
    private function request($url,$body){$ch=curl_init($url);if(!$ch)throw new RuntimeException('企业微信通知初始化失败。');curl_setopt_array($ch,array(CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>5,CURLOPT_HTTPHEADER=>array('Content-Type: application/json; charset=utf-8','User-Agent: yunshield-vpn-shop-notifier'),CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE)));$response=curl_exec($ch);$error=curl_error($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($response===false)throw new RuntimeException('企业微信通知网络失败。');if($status<200||$status>=300)throw new RuntimeException('企业微信通知 HTTP '.$status.'。');$result=json_decode(substr($response,0,4096),true);if(!is_array($result)||isset($result['errcode'])&&((int)$result['errcode']!==0))throw new RuntimeException('企业微信通知被拒绝。');return true;}
}
